import{mountShell}from'./shared/shell.js?v=0.3.0';mountShell();let filter='all';const search=document.querySelector('#search'),cards=[...document.querySelectorAll('.experiment')];function update(){let count=0;const q=search.value.trim().toLowerCase();for(const card of cards){const match=(filter==='all'||filter==='new'&&card.dataset.new==='true'||card.dataset.kind===filter)&&card.textContent.toLowerCase().includes(q);card.hidden=!match;if(match)count++;}document.querySelector('#count').textContent=`${count} experiment${count===1?'':'s'}${filter==='new'?' just added':''}`;document.querySelector('#no-results').hidden=count!==0;}document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));update();});search.oninput=update;
